void copyClipSlot(SynthProcessor& p,int from,int to){if(from<0||from>11||to<0||to>11||from==to)return;const ScopedLock lock(p.getCallbackLock());auto bank=std::make_shared<SequencerBank>(*p.sequences());bank->clips[to]=bank->clips[from];auto prefix=seqId(false,from,"");for(auto* base:p.getParameters())if(auto* parameter=dynamic_cast<AudioProcessorParameterWithID*>(base))if(parameter->paramID.startsWith(prefix)&&!CharacterFunctions::isDigit(parameter->paramID[prefix.length()])){auto* target=p.state.getParameter(seqId(false,to,parameter->paramID.substring(prefix.length())));if(target)target->setValueNotifyingHost(parameter->getValue());}p.setSequences(bank);}
