void copyArpSlot(SynthProcessor& p,int from,int to){if(from<0||from>11||to<0||to>11||from==to)return;const ScopedLock lock(p.getCallbackLock());auto bank=std::make_shared<SequencerBank>(*p.sequences());bank->arps[to]=bank->arps[from];for(auto* base:p.getParameters())if(auto* parameter=dynamic_cast<AudioProcessorParameterWithID*>(base)){auto prefix=seqId(true,from,"");if(parameter->paramID.startsWith(prefix)){auto* target=p.state.getParameter(seqId(true,to,parameter->paramID.substring(prefix.length())));if(target)target->setValueNotifyingHost(parameter->getValue());}}p.setSequences(bank);}
void importSequencerSettings(SynthProcessor& p,const var& doc){auto bank=SequencerBank::fromSerum(doc);p.setSequences(bank);for(int i=0;i<12;++i){for(bool arp:{false,true}){auto node=prop(doc,(arp?"ArpClip":"MidiClip")+String(i)),pp=params(node);auto& slot=arp?bank->arps[i]:bank->clips[i];double end=0;for(auto& note:slot.notes)end=jmax(end,note.start+note.length);double length=num(node,"regionEndBeats",jmax(4.,std::ceil(end/4)*4));p.set(seqId(arp,i,"length"),(float)length);if(arp){String shape=prop(pp,"kParamShape").toString();StringArray shapes{"Up","Down","UpDown","DownUp","Played","Chord","Converge","Diverge","Random","RandomOnce","Pattern"};int selected=shapes.indexOf(shape);if(selected<0)selected=slot.notes.empty()?0:10;p.set(seqId(true,i,"shape"),(float)selected);p.set(seqId(true,i,"triplet"),(float)num(pp,"kParamTriplets",0));p.set(seqId(true,i,"gate"),(float)num(pp,"kParamGate",100)/100);p.set(seqId(true,i,"chance"),(float)num(pp,"kParamChance",100)/100);p.set(seqId(true,i,"latch"),(float)num(pp,"kParamLatch",0));p.set(seqId(true,i,"thru"),(float)num(pp,"kParamThru",0));}else {p.set(seqId(false,i,"transpose"),(float)num(pp,"kParamTranspose",0));p.set(seqId(false,i,"span"),prop(pp,"kParamSpanKeyboardMode").toString()=="Mono"?1:0);}}}
 // Loading a preset prepares its clip bank but does not unexpectedly start a phrase.
 p.set("seqClipEnabled",0);p.set("seqRecord",0);p.set("seqClipSlot",(float)bank->preview);
}
void SynthProcessor::setSequences(std::shared_ptr<const SequencerBank> bank){const ScopedLock lock(sequenceEditLock);auto old=std::atomic_exchange(&sequenceBank,std::move(bank));if(old)retiredSequences.push_back(std::move(old));retiredSequences.erase(std::remove_if(retiredSequences.begin(),retiredSequences.end(),[](auto& item){return item.use_count()==1;}),retiredSequences.end());}
bool SynthProcessor::sequenceArpEnabled()const{auto a=std::atomic_load(&importedAssets);return value(a&&a->expansion&&a->expansion->arpEnabled?"arp":"keyboardArp")>.5f;}
void SynthProcessor::setSequenceArpEnabled(bool on){auto a=std::atomic_load(&importedAssets);set(a&&a->expansion&&a->expansion->arpEnabled?"arp":"keyboardArp",on?1:0);}
void SynthProcessor::drainSequenceRecording(){const ScopedLock lock(sequenceEditLock);for(int slot=0;slot<12;++slot){float recorded=clipRecordedLength[slot].exchange(0);if(recorded>value(seqId(false,slot,"length")))set(seqId(false,slot,"length"),jmin(256.f,std::ceil(recorded/4)*4));}if(sequenceRecordFifo.getNumReady()==0)return;auto next=std::make_shared<SequencerBank>(*sequences());int start1,size1,start2,size2;sequenceRecordFifo.prepareToRead(sequenceRecordFifo.getNumReady(),start1,size1,start2,size2);auto consume=[&](int start,int size){for(int i=start;i<start+size;++i){auto event=sequenceRecorded[i];int quant=(int)value("seqRecordQuant");if(event.kind==0&&quant>0){double grid=std::pow(2.,1-quant);event.start=std::round(event.start/grid)*grid;event.length=jmax(grid,std::round(event.length/grid)*grid);}auto& slot=next->clips[jlimit(0,11,event.slot)];if(event.kind==0&&slot.notes.size()<512)slot.notes.push_back({event.start,event.length,event.pitch,event.channel,event.value,1});else if(event.kind==1){auto lane=std::find_if(slot.lanes.begin(),slot.lanes.end(),[&](auto& l){return l.target==event.target&&l.channel==event.channel;});if(lane==slot.lanes.end()){slot.lanes.push_back({event.target,event.channel,{}});lane=slot.lanes.end()-1;}if(lane->points.size()<4096)lane->points.push_back({event.start,event.value});std::stable_sort(lane->points.begin(),lane->points.end(),[](auto a,auto b){return a.time<b.time;});}}};consume(start1,size1);consume(start2,size2);sequenceRecordFifo.finishedRead(size1+size2);setSequences(next);}
bool SynthProcessor::importSequenceMidi(int slot,const File& file,String& error){auto stream=file.createInputStream();MidiFile midi;if(!stream||!midi.readFrom(*stream)||midi.getTimeFormat()<=0){error="Choose a standard PPQ MIDI file.";return false;}auto bank=std::make_shared<SequencerBank>(*sequences());auto& target=bank->clips[jlimit(0,11,slot)];target={};target.name=file.getFileNameWithoutExtension();double ticks=midi.getTimeFormat(),end=0;for(int track=0;track<midi.getNumTracks();++track){auto notes=*midi.getTrack(track);notes.updateMatchedPairs();for(int k=0;k<notes.getNumEvents();++k){auto* item=notes.getEventPointer(k);auto& message=item->message;if(message.isNoteOn()&&item->noteOffObject&&target.notes.size()<512){double start=message.getTimeStamp()/ticks,length=(item->noteOffObject->message.getTimeStamp()-message.getTimeStamp())/ticks;target.notes.push_back({jlimit(0.,256.,start),jlimit(.01,256.,length),message.getNoteNumber(),message.getChannel(),message.getFloatVelocity(),1});end=jmax(end,start+length);}else if(message.isController()||message.isPitchWheel()||message.isChannelPressure()){int id=message.isController()?message.getControllerNumber():message.isPitchWheel()?128:129;float value=message.isController()?message.getControllerValue()/127.f:message.isPitchWheel()?message.getPitchWheelValue()/16383.f:message.getChannelPressureValue()/127.f;auto lane=std::find_if(target.lanes.begin(),target.lanes.end(),[&](auto& l){return l.target==id&&l.channel==message.getChannel();});if(lane==target.lanes.end()){target.lanes.push_back({id,message.getChannel(),{}});lane=target.lanes.end()-1;}if(lane->points.size()<4096)lane->points.push_back({message.getTimeStamp()/ticks,value});}}}for(auto& lane:target.lanes)std::stable_sort(lane.points.begin(),lane.points.end(),[](auto a,auto b){return a.time<b.time;});setSequences(bank);set(seqId(false,slot,"length"),(float)jlimit(.25,256.,std::ceil(end/4)*4));return true;}
bool SynthProcessor::exportSequenceMidi(int slot,const File& file,String& error){
 auto bank=sequences();auto source=bank->clips[jlimit(0,11,slot)];std::stable_sort(source.notes.begin(),source.notes.end(),[](auto& a,auto& b){return a.start<b.start;});MidiMessageSequence track;std::array<double,16> freeAt{};
 auto add=[&](MidiMessage message,double beat){message.setTimeStamp(beat*960);track.addEvent(message);};
 for(auto& note:source.notes){if(note.muted)continue;bool expression=!note.pitchCurve.empty()||note.expressionX!=0||note.expressionY!=0||note.expressionZ!=0;int channel=note.channel;
  if(expression){channel=0;for(int c=2;c<=16;++c){bool busy=freeAt[c-1]>note.start;for(auto& other:source.notes)if(other.channel==c&&other.pitchCurve.empty()&&other.expressionX==0&&other.expressionY==0&&other.expressionZ==0&&other.start<note.start+note.length&&other.start+other.length>note.start)busy=true;if(!busy){channel=c;break;}}if(channel==0){error="MIDI export supports up to 15 simultaneous independent expression notes.";return false;}freeAt[channel-1]=note.start+note.length;
   for(auto cc:std::array<std::pair<int,int>,4>{{{101,0},{100,0},{6,24},{100,127}}})add(MidiMessage::controllerEvent(channel,cc.first,cc.second),note.start);add(MidiMessage::controllerEvent(channel,74,roundToInt(note.expressionX*127)),note.start);add(MidiMessage::controllerEvent(channel,71,roundToInt(note.expressionY*127)),note.start);add(MidiMessage::channelPressureChange(channel,roundToInt(note.expressionZ*127)),note.start);
   for(int i=0;i<=64;++i){double fraction=i/64.;float bend=sequenceCurveValue(note.pitchCurve,fraction);add(MidiMessage::pitchWheel(channel,jlimit(0,16383,8192+roundToInt(bend/24*8191))),note.start+fraction*note.length);}}
  add(MidiMessage::noteOn(channel,note.pitch,note.velocity),note.start);add(MidiMessage::noteOff(channel,note.pitch),note.start+note.length);
 }
 for(auto& lane:source.lanes)if(lane.target<130)for(auto point:lane.points){auto event=lane.target<128?MidiMessage::controllerEvent(lane.channel,lane.target,roundToInt(point.value*127)):lane.target==128?MidiMessage::pitchWheel(lane.channel,roundToInt(point.value*16383)):MidiMessage::channelPressureChange(lane.channel,roundToInt(point.value*127));add(event,point.time);}add(MidiMessage::endOfTrack(),value(seqId(false,slot,"length")));MidiFile midi;midi.setTicksPerQuarterNote(960);midi.addTrack(track);auto stream=file.createOutputStream();if(!stream){error="Cannot write MIDI file.";return false;}stream->setPosition(0);stream->truncate();if(!midi.writeTo(*stream)){error="MIDI export failed.";return false;}return true;
}


